// Code generated by protoc-gen-typescript-http. DO NOT EDIT.

function encodeAdminQuery(fields: ReadonlyArray<readonly [string, unknown]>): string[] {
  return fields.flatMap(([name, value]) => {
    if (value === undefined || value === null) return [];
    const items: unknown[] = Array.isArray(value) ? value : [value];
    return items.map((item) => {
      const encoded = typeof item === 'object' ? JSON.stringify(item) : String(item);
      return `${encodeURIComponent(name)}=${encodeURIComponent(encoded)}`;
    });
  });
}

interface TransportMeta {
  service: string;
  method: string;
}

export interface ClientTransport {
  unary(
    path: string,
    method: string,
    body: null | string,
    meta: TransportMeta,
  ): Promise<unknown>;
  serverStream<T>(path: string, meta: TransportMeta): ServerStream<T>;
  duplexStream<TIn, TOut>(path: string, meta: TransportMeta): DuplexStream<TIn, TOut>;
}

export interface ServerStream<T> {
  onEvent(listener: (data: T) => void): () => void;
  onError(handler: (error: Error) => void): void;
  close(): void;
}

export interface DuplexStream<TIn, TOut> extends ServerStream<TOut> {
  send(data: TIn): void;
}

