// 在线会话
export type OnlineSession = {
  clientType?: ClientType_ClientType;
  // 是否为当前请求所属会话（仅 ListMyOnlineSession 场景有意义）
  current?: boolean;
  deviceId?: string;
  ipAddress?: string;
  // 会话令牌对 ID（JWT jti，唯一标识一次令牌签发）
  jti?: string;
  loginAt?: wellKnownTimestamp;
  tenantId?: number;
  userAgent?: string;
  userId?: number;
  username?: string;
};

// 查询在线会话列表 - 请求
export type ListOnlineSessionRequest = {
  // 关键词过滤（模糊匹配用户名 / IP），留空返回全部
  keyword?: string;
  // 页码（从 1 开始）
  page?: number;
  // 每页数量
  pageSize?: number;
};

// 查询在线会话列表 - 回应
export type ListOnlineSessionResponse = {
  items?: OnlineSession[];
  total?: number;
};

// 强制下线指定会话 - 请求
export type ForceLogoutSessionRequest = {
  clientType?: ClientType_ClientType;
  jti?: string;
  userId?: number;
};

// 强制下线指定会话 - 回应
export type ForceLogoutSessionResponse = Record<string, never>;

// 查询当前登录用户的在线会话 - 请求（无参数，用户身份取自认证上下文）
export type ListMyOnlineSessionRequest = Record<string, never>;

// 当前用户强制下线自己的指定会话 - 请求
export type RevokeMyOnlineSessionRequest = {
  clientType?: ClientType_ClientType;
  jti?: string;
};

// 当前用户强制下线自己的指定会话 - 回应
export type RevokeMyOnlineSessionResponse = Record<string, never>;

// 在线会话管理服务（在线用户列表 + 强制下线）
export interface OnlineSessionService {
  // 查询在线会话列表
  ListOnlineSession(
    request: ListOnlineSessionRequest,
  ): Promise<ListOnlineSessionResponse>;
  // 强制下线指定会话
  ForceLogoutSession(
    request: ForceLogoutSessionRequest,
  ): Promise<ForceLogoutSessionResponse>;
  // 查询当前登录用户的在线会话（个人中心自助视图）
  ListMyOnlineSession(
    request: ListMyOnlineSessionRequest,
  ): Promise<ListOnlineSessionResponse>;
  // 当前用户强制下线自己的指定会话
  RevokeMyOnlineSession(
    request: RevokeMyOnlineSessionRequest,
  ): Promise<RevokeMyOnlineSessionResponse>;
}

